import sys
from collections import defaultdict

def count_damn_rhombi(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def dfs(node, parent, depth, path, visited):
        if node in visited:
            return
        visited.add(node)
        path[node] = depth
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            dfs(neighbor, node, depth + 1, path, visited)

    damn_rhombi = 0

    for start in range(1, n + 1):
        path = [-1] * (n + 1)
        visited = set()
        dfs(start, -1, 0, path, visited)

        for b in graph[start]:
            for d in graph[start]:
                if b >= d:
                    continue
                for c in graph[b]:
                    if c in graph[d] and c != start and c != b and c != d:
                        damn_rhombi += 1

    return damn_rhombi // 2

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
edges = [(int(input[i * 2 + 2]), int(input[i * 2 + 3])) for i in range(m)]
print(count_damn_rhombi(n, edges))
